package application

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"time"

	"github.com/oublie6/awesome-zero-platform/server/business/doudizhu/domain"
)

// Server-managed fairness deliberately changes the trust model: entropy for
// all three seats is generated by the server before the public beacon is
// available. These bytes are NOT independently player-contributed randomness.
// The future committed beacon and versioned final record still permit an
// authorized participant to verify the deterministic deal after completion.
const serverManagedPhrase = "server-managed-v1"

type managedSeatMaterial struct {
	seat   domain.HandSeat
	random [32]byte
	digest domain.ContributionDigest
}

// prepareManagedContributions runs inside the exact room.hand.start SQL
// transaction. Commitments, encrypted reveal records, domain transitions and
// the command receipt are committed together or not at all. No client secret,
// plaintext contribution or protected record is emitted in an outbox payload.
func (s *Service) prepareManagedContributions(
	ctx context.Context, tx Transaction, hand *domain.Hand,
	seats [3]domain.HandSeat, commandID string, now time.Time,
) ([]domain.Event, error) {
	if hand == nil || hand.Snapshot().FairnessMode != domain.FairnessModeServerManaged {
		return nil, fmt.Errorf("%w: server-managed fairness mode", ErrInvalidCommand)
	}
	var material [3]managedSeatMaterial
	defer func() {
		for i := range material {
			clearBytes(material[i].random[:])
		}
	}()
	phraseHash := sha256.Sum256([]byte(serverManagedPhrase))
	events := make([]domain.Event, 0, 9)
	for index, seat := range seats {
		material[index].seat = seat
		if _, err := rand.Read(material[index].random[:]); err != nil {
			return nil, fmt.Errorf("generate server-managed contribution: %w", err)
		}
		material[index].digest = computeContributionDigest(hand.Snapshot().ID, seat.Seat,
			material[index].random, phraseHash)
		commitment := domain.ComputeClientCommitment(hand.Snapshot().ID, seat.Seat, material[index].digest)
		accepted, err := hand.SubmitCommit(seat.AccountID, commitment, hand.Snapshot().Version)
		if err != nil {
			return nil, fmt.Errorf("commit server-managed contribution: %w", err)
		}
		events = append(events, accepted...)
	}
	for _, contribution := range material {
		recordID, err := s.ids.NewID()
		if err != nil {
			return nil, fmt.Errorf("new server-managed protected record: %w", err)
		}
		accepted, err := hand.SubmitReveal(contribution.seat.AccountID, contribution.digest,
			recordID, hand.Snapshot().Version)
		if err != nil {
			return nil, fmt.Errorf("reveal server-managed contribution: %w", err)
		}
		// Keep the existing encrypted record format and AAD. The originating
		// room-start command is an audited server action for all three seats.
		plaintext, err := json.Marshal(struct {
			Version       string `json:"v"`
			HandID        string `json:"handId"`
			Seat          uint8  `json:"seat"`
			SecureRandom  string `json:"secureRandom"`
			Phrase        string `json:"phrase"`
			Normalization string `json:"normalization"`
		}{
			Version: RevealPlaintextV1, HandID: string(hand.Snapshot().ID),
			Seat: uint8(contribution.seat.Seat),
			SecureRandom: base64.RawURLEncoding.EncodeToString(contribution.random[:]),
			Phrase: serverManagedPhrase, Normalization: revealNormalizationNFKCV1,
		})
		if err != nil {
			return nil, err
		}
		protectedAAD, err := BuildContributionRecordAAD(recordID, hand.Snapshot().ID,
			contribution.seat.Seat, contribution.seat.AccountID, commandID, contribution.digest)
		if err != nil {
			clearBytes(plaintext)
			return nil, err
		}
		protected, sealErr := s.protector.Seal(ctx, plaintext, protectedAAD)
		clearBytes(plaintext)
		if sealErr != nil {
			return nil, fmt.Errorf("%w: seal managed contribution: %v", ErrProtectionFailed, sealErr)
		}
		if protected.KeyID == "" || len(protected.Nonce) == 0 ||
			len(protected.Ciphertext) == 0 || protected.AADDigest != sha256.Sum256(protectedAAD) {
			return nil, fmt.Errorf("%w: invalid managed contribution ciphertext", ErrProtectionFailed)
		}
		record := ProtectedContributionRecord{
			RecordID: recordID, HandID: hand.Snapshot().ID,
			Seat: contribution.seat.Seat, ActorAccountID: contribution.seat.AccountID,
			CommandID: commandID, ContributionDigest: contribution.digest,
			ProtectionKeyID: protected.KeyID, Nonce: append([]byte(nil), protected.Nonce...),
			Ciphertext: append([]byte(nil), protected.Ciphertext...),
			AADDigest: protected.AADDigest, CreatedAt: now,
		}
		if err := tx.InsertContributionRecord(ctx, record); err != nil {
			return nil, err
		}
		events = append(events, accepted...)
	}
	if hand.Snapshot().Phase != domain.HandWaitingPublicBeacon {
		return nil, fmt.Errorf("%w: server-managed fairness not complete", ErrInvalidCommand)
	}
	return events, nil
}
